package app.morphe.extension.chmate;
public final class SiteAuthenticationPolicyTest {
 static int checks;static void ok(boolean value,String label){if(!value)throw new AssertionError(label);checks++;}
 public static void main(String[]args){String host="bbs.animanch.com";ok(SiteAuthenticationPolicy.allow(host,"https://bbs.animanch.com/category1/",true),"board stays in authentication dialog");ok(SiteAuthenticationPolicy.allow(host,"https://bbs.animanch.com/",false),"same-site child frame allowed");ok(SiteAuthenticationPolicy.allow(host,"https://challenges.cloudflare.com/turnstile/v0/test",false),"normal user-operated Cloudflare child challenge can load");ok(!SiteAuthenticationPolicy.allow(host,"https://challenges.cloudflare.com/",true),"challenge host is not an unrestricted top-level browser");for(String url:new String[]{"http://bbs.animanch.com/","https://bbs.animanch.com.evil.invalid/","https://evil.invalid/","https://name@bbs.animanch.com/","https://bbs.animanch.com:444/","file:///private","javascript:alert(1)"})ok(!SiteAuthenticationPolicy.allow(host,url,false),"unrelated or unsafe child navigation rejected");ok(SiteAuthenticationPolicy.userAgent("bakusai.com",false,"other-site WebView").equals("Haiagaru"),"public Bakusai client does not inherit another site's browser identity");ok(SiteAuthenticationPolicy.userAgent("bakusai.com",true,"authenticated WebView").equals("authenticated WebView"),"opted-in authentication identity preserved");for(String other:new String[]{"bbs.animanch.com","jun.2chan.net","bakusai.com.evil.test"})ok(SiteAuthenticationPolicy.userAgent(other,false,"existing").equals("existing"),"unrelated host identity unchanged");System.out.println("PASS "+checks+" authentication navigation/challenge frame checks; no challenge solved or token generated");}
}
